import { ref, onMounted } from 'vue';
import axios from 'axios';
export default {
  __name: 'DockerNetworks',
  setup(__props, {
    expose: __expose
  }) {
    const networks = ref({});
    const fetchNetworks = async () => {
      try {
        const res = await axios.get('http://localhost:8081/network/list');
        networks.value = res.data;
      } catch (err) {
        console.error('获取网络列表失败', err);
      }
    };

    // 暴露方法供外部调用
    __expose({
      fetchNetworks,
      networks
    });
    onMounted(() => {
      fetchNetworks();
    });
    const __returned__ = {
      networks,
      fetchNetworks,
      ref,
      onMounted,
      get axios() {
        return axios;
      }
    };
    Object.defineProperty(__returned__, '__isScriptSetup', {
      enumerable: false,
      value: true
    });
    return __returned__;
  }
};
